template:
% 参数由系统自动注入：\def\amp{1} \def\omega{1} \def\phi{0} \def\k{0} \def\usecos{0} \def\showfive{1} \def\showperiod{1} \def\showmid{1}
% 周期 T；x 视图按 π/2 刻度对齐，约显示 1~2 个周期
\pgfmathsetmacro{\period}{2*pi/\omega}
\pgfmathsetmacro{\half}{max(pi+1.0, min(\period+0.5, 2*pi+1.0))}
\pgfmathtruncatemacro{\nmax}{ceil(\half/(pi/2))}
\pgfmathsetmacro{\xright}{\nmax*pi/2}
\pgfmathsetmacro{\xleft}{-\xright}
% y 视图围绕中线上下对称留边
\pgfmathtruncatemacro{\ytop}{ceil(abs(\k)+\amp+0.8)}
\pgfmathtruncatemacro{\ybottom}{floor(\k-\amp-0.8)}
\pgfmathsetmacro{\xrange}{\xright-\xleft}
\pgfmathsetmacro{\yrange}{\ytop-\ybottom}
\pgfmathsetmacro{\figscale}{6.5/max(\xrange,\yrange)}
\pgfmathsetmacro{\dotr}{1.6/\figscale}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  % ===== 坐标系 =====
  \draw[->, thick] (\xleft-0.6,0) -- (\xright+0.8,0) node[right] {$x$};
  \draw[->, thick] (0,\ybottom-0.5) -- (0,\ytop+0.6) node[above] {$y$};
  % x 轴刻度：π/2 整数倍 % ===== 中线 y=k =====
  \ifnum\showmid>0
    \pgfmathparse{abs(\k)>0.05}
    \ifnum\pgfmathresult=1
      \draw[dashed, gray] (\xleft,\k) -- (\xright,\k);
    \fi
  \fi
  % ===== 曲线 y=A sin(ωx+φ)+k（或余弦）=====
  \ifnum\usecos>0
    \draw[thick, domain=\xleft:\xright, samples=200, smooth] plot (\x, {\k+\amp*cos(deg(\omega*\x+\phi))});
  \else
    \draw[thick, domain=\xleft:\xright, samples=200, smooth] plot (\x, {\k+\amp*sin(deg(\omega*\x+\phi))});
  \fi
  % 函数名标注
  \ifnum\usecos>0
    \node[font=\tiny, anchor=north east, gray!50!black] at (\xright-0.2,\ytop-0.2) {$y=A\cos(\omega x+\varphi)+k$};
  \else
    \node[font=\tiny, anchor=north east, gray!50!black] at (\xright-0.2,\ytop-0.2) {$y=A\sin(\omega x+\varphi)+k$};
  \fi
  % ===== 五点法关键点 =====
  \ifnum\showfive>0
    \foreach \j in {0,1,2,3,4} {
      \pgfmathsetmacro{\xf}{(\j*pi/2-\phi)/\omega}
      \ifnum\usecos>0
        \pgfmathsetmacro{\yf}{\k+\amp*cos(\j*90)}
      \else
        \pgfmathsetmacro{\yf}{\k+\amp*sin(\j*90)}
      \fi
      \pgfmathparse{(\xf>\xleft+0.2)&&(\xf<\xright-0.2)}
      \ifnum\pgfmathresult=1
        \fill (\xf,\yf) circle [radius=\dotr pt];
      \fi
    }
  \fi
  % ===== 周期 T 标注 =====
  \ifnum\showperiod>0
    \pgfmathsetmacro{\xs}{-\phi/\omega}
    \pgfmathparse{(\xs>\xleft+0.3)&&(\xs+\period<\xright-0.3)}
    \ifnum\pgfmathresult=0
      \pgfmathsetmacro{\xs}{\xleft+0.4}
    \fi
    \pgfmathsetmacro{\yar}{\ybottom+0.5}
    \draw[<->, thick] (\xs,\yar) -- (\xs+\period,\yar);
    \draw (\xs,\yar-0.12) -- (\xs,\yar+0.12);
    \draw (\xs+\period,\yar-0.12) -- (\xs+\period,\yar+0.12);
    \node[below, font=\tiny] at (\xs+\period/2,\yar) {$T$};
  \fi
\end{tikzpicture}
